const tabs = [
  { path: '/(tabs)', label: 'Home', renderIcon: (active: boolean) => <HomeTabIcon active={active} /> },
  { path: '/(tabs)/wallet', label: 'Wallet', renderIcon: (active: boolean) => <WalletTabIcon active={active} /> },
  { path: '/(tabs)/history', label: 'History', renderIcon: (active: boolean) => <HistoryTabIcon active={active} /> },
  { path: '/(tabs)/settings', label: 'Settings', renderIcon: (active: boolean) => <SettingsTabIcon active={active} /> },
] as const;

export function BottomNav() {
  const router = useRouter();
  const pathname = usePathname();

  return (
    <View style={styles.container}>
      <View style={styles.bar}>
        {tabs.map((tab) => {
          const isHome = tab.path === '/(tabs)' && (pathname === '/' || pathname === '/(tabs)' || pathname === '/(tabs)/');
          const isActive = isHome || pathname === tab.path || pathname.startsWith(tab.path + '/');
          const activeColor = '#1D1F26';
          const inactiveColor = '#50555E';

          return (
            <TouchableOpacity
              key={tab.label}
              style={styles.tabItem}
              activeOpacity={0.7}
              onPress={() => router.push(tab.path as any)}
            >
              {tab.renderIcon(isActive)}
              <Text
                style={[
                  styles.tabLabel,
                  { color: isActive ? activeColor : inactiveColor, fontWeight: isActive ? '500' : '400' },
                ]}
              >
                {tab.label}
              </Text>
            </TouchableOpacity>
          );
        })}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    position: 'absolute',
    bottom: 0,
    left: 0,
    right: 0,
    alignItems: 'center',
    backgroundColor: '#FFFFFF',
    borderTopWidth: 1,
    borderTopColor: '#E6E7EB',
    zIndex: 100,
  },
  bar: {
    width: '100%',
    maxWidth: layout.maxContentWidth,
    flexDirection: 'row',
    justifyContent: 'space-around',
    paddingTop: 12,
    paddingBottom: Platform.OS === 'ios' ? 24 : 12,
    backgroundColor: '#FFFFFF',
  },
  tabItem: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    gap: 4,
  },
  tabLabel: {
    fontSize: 12,
    lineHeight: 14,
    letterSpacing: 0.01,
  },
});
